```javascript
// hook_jni_check.js — frida -U -f [包名] -l hook_jni_check.js --no-pause
// 或 frida -U -n [进程名] -l hook_jni_check.js
'use strict';

const SO_NAME = '[so名].so';           // 例：libnative-lib.so
const CHECK_PATTERN = /check|verify|sign|valid|auth|license|serial/i; // 符号名过滤，按需改
const DUMP_LEN = 256;

function ts() { return new Date().toISOString(); }

function hexdumpBuf(ptr, len) {
    try { return hexdump(ptr, { length: len, ansi: false }); }
    catch (e) { return '<hexdump fail: ' + e + '>'; }
}

function readStr(ptr) {
    if (ptr.isNull()) return null;
    try { return ptr.readUtf8String(); } catch (e) { return '<utf8 fail>'; }
}

// ---------- 1. 导出符号直接 attach ----------
function hookExport(mod, name) {
    const addr = mod.findExportByName(name);
    if (!addr) return false;
    hookAddr(addr, name);
    return true;
}

function hookAddr(addr, label) {
    try {
        Interceptor.attach(addr, {
            onEnter(args) {
                this.label = label;
                this.t = ts();
                this.argl = [];
                // JNI: arg0=JNIEnv*, arg1=jobject/jclass, 真实参数从 arg2 起
                for (let i = 2; i <= 5; i++) {
                    const a = args[i];
                    this.argl.push({ i: i, p: a.toString(), s: readStr(a) });
                }
                console.log(`[+] ENTER ${label} @ ${addr}  ${this.t}`);
                this.argl.forEach(a =>
                    console.log(`    arg${a.i} = ${a.p}${a.s !== null ? '  "' + a.s + '"' : ''}`));
            },
            onLeave(retval) {
                console.log(`[+] LEAVE ${label} -> ${retval}  ${ts()}`);
                // 常见返回：jboolean 0/1；jstring 指针；jint 码
