```c
// target_scan.c —— 先确认进程、模块基址、是否被句柄保护
#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

int main(int argc, char** argv) {
    const wchar_t* procName = (argc > 1) ? NULL : L"[进程名].exe";  // 占位符
    // 实际调用：L"GameName-Win64-Shipping.exe"
    wchar_t target[MAX_PATH];
    if (argc > 1) mbstowcs(target, argv[1], MAX_PATH);
    else wcscpy_s(target, MAX_PATH, procName);

    DWORD pid = 0;
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe = { sizeof(pe) };
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe)) {
        if (_wcsicmp(pe.szExeFile, target) == 0) { pid = pe.th32ProcessID; break; }
    }
    CloseHandle(snap);
    if (!pid) { wprintf(L"[-] not found: %s\n", target); return 1; }
    wprintf(L"[+] pid = %lu\n", pid);

    // 关键：PROCESS_VM_READ|WRITE|QUERY_INFORMATION 同时申请，若反作弊挂 ObRegisterCallbacks 会在此被剥权限
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION |
                           PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("[-] OpenProcess failed: %lu (可能被 ObRegisterCallbacks 剥权限)\n", GetLastError()); return 1; }
    printf("[+] handle ok (protected=%s)\n", IsProcessCritical(h, NULL) ? "critical" : "normal");

    // 模块基址
    HANDLE ms = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me = { sizeof(me) };
    for (BOOL ok = Module32FirstW(ms, &me); ok; ok = Module32NextW(ms, &me)) {
        if (wcsstr(me.szModule, L"-Win64-Shipping") || wcsstr(me.szModule, L"[模块名]"))
            wprintf(L"[+] base = 0x%p  size = 0x%X  %s\n", me.modBaseAddr, me.modBaseSize, me.szModule);
    }
    CloseHandle(ms);
    CloseHandle(h);
    return 0;
}
