    PVOID  Buffer;
    SIZE_T Size;
    SIZE_T ReturnSize;
} RW_REQUEST, *PRW_REQUEST;

static NTSTATUS ReadWriteMemory(PRW_REQUEST req, BOOLEAN bWrite) {
    PEPROCESS process = NULL;
    NTSTATUS status = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &process);
    if (!NT_SUCCESS(status)) return status;

    SIZE_T bytes = 0;
    status = MmCopyVirtualMemory(
        bWrite ? PsGetCurrentProcess() : process,
        req->Buffer,
        bWrite ? process : PsGetCurrentProcess(),
        req->Address,
        req->Size,
        KernelMode,
        &bytes);

    ObDereferenceObject(process);
    req->ReturnSize = bytes;
    return status;
}

static NTSTATUS DispatchCreateClose(PDEVICE_OBJECT dev, PIRP irp) {
    irp->IoStatus.Status = STATUS_SUCCESS;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

static NTSTATUS DispatchDeviceControl(PDEVICE_OBJECT dev, PIRP irp) {
    PIO_STACK_LOCATION stack = IoGetCurrentIrpStackLocation(irp);
    ULONG code = stack->Parameters.DeviceIoControl.IoControlCode;
    ULONG inLen = stack->Parameters.DeviceIoControl.InputBufferLength;
    NTSTATUS status = STATUS_INVALID_PARAMETER;

    if (inLen < sizeof(RW_REQUEST)) {
        irp->IoStatus.Status = status;
        irp->IoStatus.Information = 0;
        IoCompleteRequest(irp, IO_NO_INCREMENT);
        return status;
    }

    PRW_REQUEST req = (PRW_REQUEST)irp->AssociatedIrp.SystemBuffer;

    if (code == IOCTL_READ_MEM) {
        status = ReadWriteMemory(req, FALSE);
    } else if (code == IOCTL_WRITE_MEM) {
        status = ReadWriteMemory(req, TRUE);
    }

    irp->IoStatus.Status = status;
    irp->IoStatus.Information = NT_SUCCESS(status) ? sizeof(RW_REQUEST) : 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return status;
}

