static NTSTATUS MdlCopy(PEPROCESS Src, PEPROCESS Dst, PVOID SrcVa, PVOID DstVa, SIZE_T Size, BOOLEAN Write)
{
    PMDL mdl = NULL;
    PVOID mapped = NULL;
    NTSTATUS st = STATUS_SUCCESS;

    if (!SrcVa || !DstVa || !Size) return STATUS_INVALID_PARAMETER;

    // 挂到源进程上下文做映射
    KAPC_STATE apc;
    KeStackAttachProcess(Src, &apc);

    mdl = IoAllocateMdl(SrcVa, (ULONG)Size, FALSE, FALSE, NULL);
    if (!mdl) { KeUnstackDetachProcess(&apc); return STATUS_INSUFFICIENT_RESOURCES; }

    __try {
        MmProbeAndLockPages(mdl, KernelMode, Write ? IoReadAccess : IoWriteAccess);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        IoFreeMdl(mdl);
        KeUnstackDetachProcess(&apc);
        return STATUS_ACCESS_VIOLATION;
    }

    mapped = MmGetSystemAddressForMdlSafe(mdl, NormalPagePriority);
    if (!mapped) { st = STATUS_INSUFFICIENT_RESOURCES; goto done; }

    __try {
        if (Write) RtlCopyMemory(mapped, DstVa, Size);   // 用户→目标
        else       RtlCopyMemory(DstVa, mapped, Size);   // 目标→用户
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        st = STATUS_ACCESS_VIOLATION;
    }

done:
    MmUnlockPages(mdl);
    IoFreeMdl(mdl);
    KeUnstackDetachProcess(&apc);
    return st;
}

