// x64, MSVC /W4
#include <windows.h>
#include <TlHelp32.h>
#include <cstdio>

// === 占位符：按你的目标替换 ===
static const wchar_t* kProcName = L"[进程名].exe";   // 例如 L"GameClient.exe"
static const char*    kModName  = "[模块名]";        // 例如 "GameClient.exe" / "UnityPlayer.dll"

DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) {
                DWORD pid = pe.th32ProcessID;
                CloseHandle(snap);
                return pid;
            }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return 0;
}

uintptr_t GetModuleBase(DWORD pid, const char* modName) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32 me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32First(snap, &me)) {
        do {
            if (_stricmp(me.szModule, modName) == 0) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32Next(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int main() {
    DWORD pid = FindPid(kProcName);
    if (!pid) { printf("[!] process not found\n"); return 1; }
    printf("[+] pid = %lu\n", pid);

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("[!] OpenProcess failed = %lu\n", GetLastError()); return 1; }

    uintptr_t base = GetModuleBase(pid, kModName);
    printf("[+] %s base = 0x%llX\n", kModName, (unsigned long long)base);

    // === 读一个值验证通道打通 ===
    uintptr_t addr = base + 0x[偏移];        // 占位符
    uint32_t  val  = 0;
    SIZE_T    got  = 0;
    if (ReadProcessMemory(h, (LPCVOID)addr, &val, sizeof(val), &got) && got == sizeof(val))
        printf("[+] read 0x%llX = 0x%08X\n", (unsigned long long)addr, val);
    else
        printf("[!] RPM failed = %lu\n", GetLastError());

    CloseHandle(h);
    return 0;
}
```

