typedef struct _RW_REQ {
    uint32_t pid;
    uint64_t addr;
    uint64_t buf;
    uint32_t size;
} RW_REQ, *PRW_REQ;

typedef struct _BASE_REQ {
    uint32_t pid;
    wchar_t  module[64];
    uint64_t base;
    uint32_t size;
} BASE_REQ, *PBASE_REQ;

HANDLE g_dev;

static BOOL dev_open(void) {
    g_dev = CreateFileW(L"\\\\.\\NekoRW",
        GENERIC_READ | GENERIC_WRITE, 0, NULL,
        OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    return g_dev != INVALID_HANDLE_VALUE;
}

static BOOL rw_read(uint32_t pid, uint64_t addr, void* buf, uint32_t size) {
    RW_REQ r = { pid, addr, (uint64_t)buf, size };
    DWORD ret = 0;
    return DeviceIoControl(g_dev, IOCTL_READ, &r, sizeof(r), &r, sizeof(r), &ret, NULL);
}

static BOOL rw_write(uint32_t pid, uint64_t addr, const void* buf, uint32_t size) {
    RW_REQ r = { pid, addr, (uint64_t)buf, size };
    DWORD ret = 0;
    return DeviceIoControl(g_dev, IOCTL_WRITE, &r, sizeof(r), &r, sizeof(r), &ret, NULL);
}

static BOOL rw_base(uint32_t pid, const wchar_t* mod, uint64_t* base, uint32_t* size) {
    BASE_REQ r = { pid, {0}, 0, 0 };
    wcsncpy_s(r.module, 64, mod, _TRUNCATE);
    DWORD ret = 0;
    BOOL ok = DeviceIoControl(g_dev, IOCTL_BASE, &r, sizeof(r), &r, sizeof(r), &ret, NULL);
    if (ok) { *base = r.base; *size = r.size; }
    return ok;
}

