#define PHYS_MASK 0x000FFFFFFFFFF000ULL
#define PAGE_SHIFT 12
#define PTE_SHIFT 9

typedef struct _CR3_CTX {
    UINT64  Cr3;          // target DirectoryTableBase
    BOOLEAN Is5Level;     // LA57
