} MY_DPC, *PMY_DPC;

NTSTATUS Cr3CtxInit(HANDLE pid, PCR3_CTX ctx);
NTSTATUS Cr3ReadProcess(CR3_CTX* ctx, UINT64 va, VOID* buf, SIZE_T len);
NTSTATUS Cr3WriteProcess(CR3_CTX* ctx, UINT64 va, const VOID* buf, SIZE_T len);
UINT64   Cr3Translate(CR3_CTX* ctx, UINT64 va, BOOLEAN* ok);
```

