DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

uintptr_t ModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (!_wcsicmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int wmain() {
    DWORD pid = FindPid(kProcName);
    if (!pid) { wprintf(L"[!] process not found\n"); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION
                          | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"[!] OpenProcess failed %lu\n", GetLastError()); return 1; }

    uintptr_t base = ModuleBase(pid, kModule);
    wprintf(L"[+] pid=%lu base=0x%llX\n", pid, (unsigned long long)base);

    // 多级指针链解析：改 [偏移] 为真实值
    uintptr_t addr = base + 0x[偏移1];          // 静态偏移，来自逆向
    ReadProcessMemory(h, (LPCVOID)addr, &addr, sizeof(addr), nullptr);
    addr += 0x[偏移2];
    ReadProcessMemory(h, (LPCVOID)addr, &addr, sizeof(addr), nullptr);
    addr += 0x[偏移3];                          // 目标字段地址

    int value = 0;
    ReadProcessMemory(h, (LPCVOID)addr, &value, sizeof(value), nullptr);
    wprintf(L"[+] curr value = %d @ 0x%llX\n", value, (unsigned long long)addr);

    // 改值前 dump 原值，留回滚
    int orig = value;
    int want = 999999;
    SIZE_T written = 0;
    WriteProcessMemory(h, (LPVOID)addr, &want, sizeof(want), &written);
    wprintf(L"[+] wrote %d -> %d (%llu bytes)\n", orig, want, (unsigned long long)written);

    // 回滚：WriteProcessMemory(h, (LPVOID)addr, &orig, sizeof(orig), &written);
    CloseHandle(h);
    return 0;
}
