直接上干货——以下是内存读写模块的完整实现，把 `[进程名]`、`[模块名]`、`[偏移]` 替换成你的目标即可运行。

```cpp
// mem_rw.h —— 用户态读写模块（Windows x64）
#pragma once
#include <windows.h>
#include <tlhelp32.h>
#include <string>
#include <vector>
#include <cstdint>

class MemRW {
public:
    HANDLE hProc = nullptr;
    DWORD  pid   = 0;
    uintptr_t base = 0;

    bool Attach(const wchar_t* procName) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if (snap == INVALID_HANDLE_VALUE) return false;
        PROCESSENTRY32W pe{ sizeof(pe) };
        for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe)) {
            if (_wcsicmp(pe.szExeFile, procName) == 0) { pid = pe.th32ProcessID; break; }
        }
        CloseHandle(snap);
        if (!pid) return false;

        hProc = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE |
                            PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
        if (!hProc) return false;

        base = GetModuleBase(L"[模块名]");   // 例：L"TslGame.exe" / L"GameAssembly.dll"
        return base != 0;
    }

    uintptr_t GetModuleBase(const wchar_t* modName) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
        if (snap == INVALID_HANDLE_VALUE) return 0;
        MODULEENTRY32W me{ sizeof(me) };
        uintptr_t result = 0;
        for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me)) {
            if (_wcsicmp(me.szModule, modName) == 0) { result = (uintptr_t)me.modBaseAddr; break; }
        }
        CloseHandle(snap);
        return result;
    }

    template<typename T>
    T Read(uintptr_t addr) {
        T val{};
        ReadProcessMemory(hProc, (LPCVOID)addr, &val, sizeof(T), nullptr);
        return val;
    }

    template<typename T>
    bool Write(uintptr_t addr, T val) {
        DWORD old = 0;
        VirtualProtectEx(hProc, (LPVOID)addr, sizeof(T), PAGE_EXECUTE_READWRITE, &old);
        BOOL ok = WriteProcessMemory(hProc, (LPVOID)addr, &val, sizeof(T), nullptr);
        VirtualProtectEx(hProc, (LPVOID)addr, sizeof(T), old, &old);
        return ok != FALSE;
    }

    // 多级指针链：base + off0 → deref + off1 → deref + off2 ...
    uintptr_t ResolveChain(std::vector<uintptr_t> offsets) {
        if (offsets.empty()) return 0;
        uintptr_t addr = base + offsets[0];
        for (size_t i = 1; i < offsets.size(); ++i) {
            addr = Read<uintptr_t>(addr);          // 先解引用
            if (!addr || addr < 0x10000) return 0; // 空指针保护
            addr += offsets[i];
        }
        return addr;
    }
};
```

