| 平台 | Windows x64 | 用户提到 `game.exe`，按 x64 路线 |
| 需要的工具 | x64dbg、Cheat Engine、VS2022 或 MinGW | CE 用来初扫，x64dbg 验证写入点 |
| 样本与驱动 | 不需要驱动 | 外部读内存 + 写入验证用 `OpenProcess` / `WriteProcessMemory` 就够，用户态路线先跑通 |

**第一条可执行动作（本机就能跑，先 dump 原始血量值做回滚基线）**

```cpp
// hp_scan.cpp  —  x64 Release 编译，无需管理员（目标未开反作弊时）
// cl /O2 /EHsc hp_scan.cpp /link /OUT:hp_scan.exe
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>
#include <string>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{ sizeof(pe) }; DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap); return pid;
}

static ULONGLONG ModuleBase(DWORD pid, const wchar_t* mod, DWORD* sizeOut) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    MODULEENTRY32W me{ sizeof(me) }; ULONGLONG base = 0;
    if (Module32FirstW(snap, &me)) do {
        if (!_wcsicmp(me.szModule, mod)) {
            base = (ULONGLONG)me.modBaseAddr;
            if (sizeOut) *sizeOut = me.modBaseSize;
            break;
        }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap); return base;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = argc > 1 ? argv[1] : L"game.exe";
    const wchar_t* mod  = argc > 2 ? argv[2] : L"game.exe";
    DWORD pid = FindPid(proc);
    if (!pid) { wprintf(L"[-] 进程未找到: %s\n", proc); return 1; }
    DWORD msize = 0;
    ULONGLONG base = ModuleBase(pid, mod, &msize);
    wprintf(L"[+] pid=%lu  module=%s  base=0x%llX  size=0x%X\n",
            pid, mod, base, msize);

    HANDLE h = OpenProcess(
        PROCESS_QUERY_INFORMATION | PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION,
        FALSE, pid);
    if (!h) { wprintf(L"[-] OpenProcess 失败: %lu\n", GetLastError()); return 1; }

    // 扫描前先 dump 前 16MB 原始字节做回滚基线
    std::vector<BYTE> snap(1 << 24);
    SIZE_T got = 0;
    if (ReadProcessMemory(h, (LPCVOID)base, snap.data(), snap.size(), &got) && got) {
        std::wstring out = L"hp_baseline.bin";
        HANDLE f = CreateFileW(out.c_str(), GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS,
                               FILE_ATTRIBUTE_NORMAL, nullptr);
        DWORD w = 0;
        WriteFile(f, snap.data(), (DWORD)got, &w, nullptr);
        CloseHandle(f);
        wprintf(L"[+] 基线已 dump: %s  (%lu 字节)  — 回滚时写回同地址即可\n", out.c_str(), w);
    }
    CloseHandle(h);
    return 0;
}
```

跑完后，把 `hp_baseline.bin` 留在目录里作为回滚基线。接下来派给 `dynamic` 的是真正的定位工作：CE 初扫（数据类型 float/int32 都试，`Unknown initial value` → 掉血 `Decreased` → 回血 `Increased` 三轮收窄）→ 得到动态地址 → 回溯多级指针链到 `game.exe+[偏移]` → 用 `WriteProcessMemory` 改值验证界面变化 → 落库偏移表。

