// lock.cpp —— 外部读写，编译：cl /EHsc /O2 lock.cpp
#include <windows.h>
#include <TlHelp32.h>
#include <cmath>
#include <cstdio>
#include <vector>
#include <cstring>

struct Vec3 { float x, y, z; };
static HANDLE g_h = nullptr;
static uintptr_t g_base = 0;

template<typename T> inline T R(uintptr_t a) {
    T v{}; ReadProcessMemory(g_h, (LPCVOID)a, &v, sizeof(T), nullptr); return v;
}

bool Attach(const wchar_t* proc) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
        if (!_wcsicmp(pe.szExeFile, proc)) {
            g_h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_QUERY_INFORMATION | PROCESS_VM_OPERATION, FALSE, pe.th32ProcessID);
            if (!g_h) return false;
            HANDLE m = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pe.th32ProcessID);
            MODULEENTRY32W me{ sizeof(me) };
            for (BOOL k = Module32FirstW(m, &me); k; k = Module32NextW(m, &me))
                if (_wcsicmp(me.szModule, L"") != 0 && me.modBaseSize > 0x1000000 && !g_base)
                    g_base = (uintptr_t)me.modBaseAddr;   // 主模块兜底，实际用 [模块名]
            CloseHandle(m);
            CloseHandle(snap);
            return true;
        }
    CloseHandle(snap);
    return false;
}
```

