```cpp
// OpenProcess + 模块基址获取，Windows x64
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <stdio.h>
#include <vector>

DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

// 模块基址（x64 下一定用 TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32）
uintptr_t GetModuleBase(DWORD pid, const wchar_t* modName) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (_wcsicmp(me.szModule, modName) == 0) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int wmain() {
    const wchar_t* PROC = L"[进程名].exe";      // 占位符：填目标进程名
    const wchar_t* MOD  = L"[模块名].exe";       // 占位符：填承载 UWorld/GObjects 的模块

    DWORD pid = GetPid(PROC);
    if (!pid) { wprintf(L"pid not found\n"); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed: %lu\n", GetLastError()); return 1; }

    uintptr_t base = GetModuleBase(pid, MOD);
    wprintf(L"pid=%lu base=%p\n", pid, (void*)base);
    CloseHandle(h);
    return 0;
}
```

